def semver_sort(versions):
    def parse_version(v):
        # Split off build metadata (everything after '+')
        if '+' in v:
            v, _ = v.split('+', 1)

        # Split core version and pre-release
        if '-' in v:
            core, prerelease = v.split('-', 1)
        else:
            core = v
            prerelease = None

        # Parse core version (MAJOR.MINOR.PATCH)
        parts = core.split('.')
        major = int(parts[0]) if len(parts) > 0 else 0
        minor = int(parts[1]) if len(parts) > 1 else 0
        patch = int(parts[2]) if len(parts) > 2 else 0

        # Parse pre-release identifiers
        if prerelease:
            prerelease_ids = prerelease.split('.')
            # Convert to tuples: (is_numeric, numeric_value or string)
            parsed_ids = []
            for identifier in prerelease_ids:
                if identifier.isdigit():
                    parsed_ids.append((0, int(identifier)))  # 0 sorts before 1
                else:
                    parsed_ids.append((1, identifier))  # 1 for non-numeric
            prerelease_tuple = tuple(parsed_ids)
        else:
            prerelease_tuple = None

        return (major, minor, patch, prerelease_tuple)

    def sort_key(v):
        major, minor, patch, prerelease_tuple = parse_version(v)

        # For sorting: version without prerelease > version with prerelease
        # So we use (major, minor, patch, has_prerelease, prerelease_tuple)
        # where has_prerelease=0 means it has a prerelease (sorts first), 1 means no prerelease
        if prerelease_tuple is None:
            return (major, minor, patch, 1)  # 1 means no prerelease (sorts after)
        else:
            return (major, minor, patch, 0, prerelease_tuple)  # 0 means has prerelease (sorts first)

    # Stable sort: maintain input order for equal precedence
    return sorted(versions, key=sort_key)

